{
  "IP": "neorv32_cpu_icc",
  "Conceptual Assets": [
    {
      "Concept ID": "C1",
      "Concept Name": "Transmit payload data",
      "Unit": "neorv32_cpu_icc",
      "Information": "Payload words written through the CSR interface are queued for transmission to the ICC peer, and delivery depends on the FIFO and its acknowledgment flow. The FIFO is a buffering path, so the payload crosses through csr_wdata_i and icc_tx_o.dat without an independently held RTL signal.",
      "Rubric": {
        "Confidentiality": "yes",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "An integrator may treat transmitted payloads as secret, and the FIFO carries them to the externally observable icc_tx_o.dat at line 86. The FIFO accepts csr_wdata_i at line 81, so changing a queued word changes the transmitted payload. Withholding icc_rx_i.ack at line 85 can prevent the FIFO from advancing and keep the payload from leaving through icc_tx_o.dat.",
      "Objectives At Risk": [
        "C",
        "I",
        "A"
      ],
      "Attack": "An attacker could inject or alter CSR-written payloads and withhold transmission acknowledgments to corrupt or stall the ICC transfer.",
      "Enters Through": [
        "csr_wdata_i"
      ],
      "Leaves Through": [
        "icc_tx_o.dat"
      ],
      "Entry Lines": [
        81
      ],
      "Held Lines": [],
      "Exit Lines": [
        86
      ]
    },
    {
      "Concept ID": "C2",
      "Concept Name": "Received payload data",
      "Unit": "neorv32_cpu_icc",
      "Information": "A payload word presented by the ICC peer on icc_rx_i.dat is returned to software through the CSR readback path when the receive-ready indication is asserted. The unit does not store the word independently; it directly transfers it to csr_rdata_o.",
      "Rubric": {
        "Confidentiality": "yes",
        "Integrity": "no",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Received payload may contain secret information and is exposed at csr_rdata_o by the assignment at line 52. The rdy condition at line 51 can withhold the received word, so an attacker controlling the receive-valid condition can block its required readback.",
      "Objectives At Risk": [
        "C",
        "A"
      ],
      "Attack": "An attacker could expose the received payload through the CSR readback or suppress the receive-ready condition so software cannot obtain it.",
      "Enters Through": [
        "icc_rx_i.dat"
      ],
      "Leaves Through": [
        "csr_rdata_o"
      ],
      "Entry Lines": [
        52
      ],
      "Held Lines": [],
      "Exit Lines": [
        52
      ]
    },
    {
      "Concept ID": "C3",
      "Concept Name": "CSR readback selection",
      "Unit": "neorv32_cpu_icc",
      "Information": "The CSR address and receive-valid decision select whether the readback path returns zero, receive status, transmit-space status, or received payload data. Correct selection is required for software to observe the intended ICC register value.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "The address and receive-valid selection controls which value reaches csr_rdata_o at lines 46-53, so altering the decision can return an incorrect value. An unmatched address or a false receive-ready decision can withhold the required readback through the default and conditional logic at lines 45-53.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker could steer the CSR readback selection to return status or zero instead of the requested received data, or prevent a valid read from completing.",
      "Enters Through": [],
      "Leaves Through": [],
      "Entry Lines": [],
      "Held Lines": [
        46,
        47,
        51
      ],
      "Exit Lines": []
    }
  ],
